const app=document.querySelector('#app-root'),layers=document.querySelector('#layer-root'),live=document.querySelector('#live-region'),note=document.querySelector('#review-note'),toolbar=document.querySelector('.prototype-toolbar');
const state={scenario:'basics',openSection:'basics',showSummary:false,layer:null,trigger:null,menu:false,navigated:'',overCapacity:true,ingredientErrors:false,ingredientTouched:{},touched:{},fields:{title:'',author:'Marta Cooks has a name that is intentionally much too long for this demonstration',time:'4x',servings:'two',ingredient:'',quantity:'two cans'}};
const basicsCopy={title:'Enter a recipe title.',author:'Author is too long. Shorten it before saving.',time:'Enter cooking time as a whole number of minutes.',servings:'Enter servings as a whole number.'};
function announce(t){live.textContent='';requestAnimationFrame(()=>live.textContent=t)}function whole(v){return v===''||/^[1-9]\d*$/.test(v)}function quantity(v){return v===''||/^(?:[0-9]+(?:[.,][0-9]+)?|[½¼¾])(?:\s*(?:\/|–|-)\s*(?:[0-9]+(?:[.,][0-9]+)?|[½¼¾]))?$/.test(v)}function partialQuantity(v){return /^\d+(?:[.,]\d*)?$/.test(v)||/^\d+\s*(?:\/|–|-)\s*(?:\d+(?:[.,]\d*)?)?$/.test(v)}function titleInvalid(){return state.fields.title===''&&(state.touched.title||state.showSummary)}function authorInvalid(){return state.fields.author.length>48}function fieldInvalid(n){if(n==='title')return titleInvalid();if(n==='author')return authorInvalid();if(n==='time'||n==='servings')return !whole(state.fields[n]);return false}function ingredientInvalid(n){if(n==='ingredient')return state.ingredientErrors&&state.fields.ingredient==='';const value=state.fields.quantity;if(quantity(value))return false;return state.ingredientErrors||state.ingredientTouched.quantity||!partialQuantity(value)}function basicIssues(){return ['title','author','time','servings'].filter(fieldInvalid)}function issueCount(){return basicIssues().length+(state.overCapacity?1:0)}
function field(name,label,value,hint=''){const invalid=fieldInvalid(name),copy=basicsCopy[name];return `<div><label class="field-label" for="${name}">${label}${hint?`<span class="field-hint">${hint}</span>`:''}</label><input id="${name}" name="${name}" value="${value}" ${invalid?`aria-invalid="true" aria-describedby="error-${name}"`:''}>${invalid?`<p class="field-error" id="error-${name}"><span aria-hidden="true">!</span>${copy}</p>`:''}</div>`}
function header(name,meta,expanded,errors=0){const count=errors?`, ${errors} ${errors===1?'error':'errors'}`:'';return `<button class="section-toggle" type="button" data-section="${name.toLowerCase()}" aria-expanded="${expanded}" aria-label="${name}${count}"><span><strong>${name}</strong><small>${errors?`${errors} ${errors===1?'error':'errors'} · `:''}${meta}</small></span><span class="chevron" aria-hidden="true">${expanded?'⌃':'⌄'}</span></button>`}
function summary(){if(!state.showSummary||!issueCount())return '';const items=basicIssues().map(n=>`<li><a href="#${n}" data-focus="${n}">${basicsCopy[n]}</a></li>`).join('');return `<section class="error-summary" tabindex="-1" aria-labelledby="summary-title"><div class="summary-mark" aria-hidden="true">!</div><div><h2 id="summary-title">${issueCount()} ${issueCount()===1?'issue':'issues'} need attention</h2><p>Fix the fields below, then save again.</p>${items?`<h3>Basics · ${basicIssues().length}</h3><ul>${items}</ul>`:''}${state.overCapacity?'<h3>Ingredients · 1</h3><ul><li><a href="#ingredients" data-focus="ingredients">Remove 2 ingredients before saving.</a></li></ul>':''}</div></section>`}
function basics(){const open=state.openSection==='basics';return `<section class="accordion-section ${open?'is-expanded':''}">${header('Basics','7 fields',open,basicIssues().length)}${open?`<div class="section-panel basics-form"><div class="basics-grid"><div class="full-width">${field('title','Recipe title',state.fields.title)}</div><div><label class="field-label" for="source">Source</label><button id="source" class="field-button" type="button" aria-label="Source, Instagram"><span>Instagram</span><span aria-hidden="true">⌄</span></button></div>${field('author','Author',state.fields.author)}${field('time','Cooking time (min)',state.fields.time,'Whole minutes only')}${field('servings','Servings',state.fields.servings)}<div class="wide-choice"><div class="choice-heading"><span>Difficulty</span><button type="button" class="clear-action">Clear</button></div><div class="segmented" role="group" aria-label="Difficulty"><button type="button">Easy</button><button type="button" aria-pressed="true">Moderate</button><button type="button">Hard</button></div></div><div class="wide-choice"><div class="choice-heading"><span>Personal rating <span class="visually-hidden">4 out of 5</span></span><button type="button" class="clear-action">Clear</button></div><div class="rating-row" role="group" aria-label="Personal rating">${[1,2,3,4,5].map(n=>`<button type="button" class="star-button ${n<=4?'is-selected':''}" aria-label="Rate ${n} out of 5" aria-pressed="${n===4}">${n<=4?'★':'☆'}</button>`).join('')}</div></div></div></div>`:''}</section>`}
function ingredients(){const open=state.openSection==='ingredients',errs=state.overCapacity?1:0;return `<section class="accordion-section ${open?'is-expanded':''}" id="ingredients" tabindex="-1">${header('Ingredients',state.overCapacity?'52 of 50':'50 of 50',open,errs)}${open?`<div class="section-panel ingredient-panel">${state.overCapacity?`<div class="capacity-error" role="alert"><strong>52 of 50 ingredients</strong><p>Remove 2 ingredients before saving.</p><button type="button" class="capacity-remove" data-remove-excess>Remove 2 ingredients</button></div>`:''}<p class="section-help">${state.overCapacity?'Ingredient limit reached. Remove one to add another.':'Ingredient limit reached. Remove one to add another.'}</p><div class="ingredient-list"><button type="button" class="ingredient-row" data-edit-ingredient aria-label="Edit Chickpeas, 2 cans"><span><strong>Chickpeas</strong><small>2 cans · No unit</small></span><span aria-hidden="true">›</span></button><div class="ingredient-row muted-row"><span><strong>+ ${state.overCapacity?'51':'49'} more ingredients</strong><small>Dense count shown for validation</small></span></div></div><button type="button" class="add-ingredient" disabled aria-describedby="ingredient-limit">Add ingredient</button><span id="ingredient-limit" class="visually-hidden">Ingredient limit reached. Remove one to add another.</span></div>`:''}</section>`}
function instructions(){const open=state.openSection==='instructions';return `<section class="accordion-section ${open?'is-expanded':''}">${header('Instructions','8 steps',open)}${open?'<div class="section-panel"><p class="section-help">Instruction editing remains unchanged in this validation study.</p></div>':''}</section>`}
function nav(){return `<nav class="global-navigation" aria-label="Main navigation"><button type="button" data-guard="recipes" aria-current="page"><b aria-hidden="true">☰</b><span>Recipes</span></button><button type="button" data-guard="collections"><b aria-hidden="true">▦</b><span>Collections</span></button><button type="button" class="global-add" data-guard="add" aria-label="Add recipe">+</button><button type="button" data-guard="notifications"><b aria-hidden="true">●</b><span>Notifications</span></button><button type="button" data-guard="profile"><b aria-hidden="true">○</b><span>Profile</span></button></nav>`}
function menu(){return state.menu?`<div class="overflow-menu" role="menu" aria-label="Recipe actions"><button type="button" data-guard="view">View recipe</button><button type="button" data-guard="focus">Cooking focus</button><button type="button" data-guard="manage">Manage media</button><button type="button" data-aux="Media">Media</button><button type="button" data-aux="Import info">Import info</button></div>`:''}
function editor(){if(state.navigated)return `<header class="compact-edit-header"><button class="header-icon" type="button" aria-label="Back to recipe">‹</button><strong class="recipe-title">Smoky Tomato &amp; Butter Bean Stew</strong><button class="save-action" type="button">Save</button><button class="header-icon" type="button" aria-label="More recipe actions">•••</button></header><main class="editor-scroll restored"><div class="restored-state"><span aria-hidden="true">✓</span><h2>${state.navigated==='saved'?'Recipe saved for this prototype.':'Recipe view restored for this prototype.'}</h2><p>${state.navigated==='saved'?'All validation issues were corrected before Save.':'Discard is the only action that leaves this dirty edit draft.'}</p></div></main>${nav()}`;return `<header class="compact-edit-header"><button class="header-icon" type="button" data-guard="back" aria-label="Back to recipe">‹</button><strong class="recipe-title">Smoky Tomato &amp; Butter Bean Stew</strong><button class="save-action" type="button" data-save aria-label="Save recipe">Save</button><button class="header-icon overflow-trigger" type="button" data-menu aria-label="More recipe actions">•••</button></header>${menu()}<main class="editor-scroll">${summary()}${basics()}${ingredients()}${instructions()}<p class="auxiliary-message" aria-live="polite"></p></main>${nav()}`}
function ingredientSheet(){const nbad=ingredientInvalid('ingredient'),qbad=ingredientInvalid('quantity');return `<div class="sheet-backdrop" data-dismiss></div><section class="bottom-sheet ingredient-sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle" data-swipe aria-hidden="true"></div><header><h2 id="sheet-title">Edit ingredient</h2><button type="button" data-dismiss data-initial-focus aria-label="Close">×</button></header><div class="sheet-body"><label class="field-label" for="ingredient">Ingredient</label><input id="ingredient" name="ingredient" value="${state.fields.ingredient}" ${nbad?'aria-invalid="true" aria-describedby="ingredient-error"':''}>${nbad?'<p class="field-error" id="ingredient-error"><span aria-hidden="true">!</span>Enter an ingredient name.</p>':''}<label class="field-label" for="quantity">Quantity</label><input id="quantity" name="quantity" value="${state.fields.quantity}" ${qbad?'aria-invalid="true" aria-describedby="quantity-error"':''}>${qbad?'<p class="field-error" id="quantity-error"><span aria-hidden="true">!</span>Enter a quantity using numbers, fractions, or a range.</p>':''}<label class="field-label" for="unit">Unit</label><button id="unit" class="field-button" type="button" aria-label="Unit, No unit"><span>No unit</span><span aria-hidden="true">⌄</span></button><button type="button" class="sheet-primary" data-done>Done</button></div></section>`}
function guardSheet(){return `<div class="sheet-backdrop" data-dismiss></div><section class="bottom-sheet guard-sheet" role="dialog" aria-modal="true" aria-labelledby="guard-title"><div class="sheet-handle" data-swipe aria-hidden="true"></div><header><h2 id="guard-title">Unsaved changes</h2><button type="button" data-dismiss data-initial-focus aria-label="Close">×</button></header><div class="sheet-body"><p class="guard-copy">Save changes before leaving this recipe?</p><button type="button" class="sheet-primary" data-guard-save>Save changes</button><button type="button" class="sheet-danger" data-discard>Discard changes</button><button type="button" class="sheet-secondary" data-dismiss>Keep editing</button></div></section>`}
function renderLayer(){app.inert=Boolean(state.layer);toolbar.inert=Boolean(state.layer);if(!state.layer){layers.replaceChildren();return}layers.innerHTML=state.layer==='ingredient'?ingredientSheet():guardSheet()}
function render(){app.innerHTML=editor();renderLayer();note.innerHTML='<h2>Approved Save treatment</h2><ul><li>Inline summary appears after an unsuccessful Save.</li><li>Links expand and focus their related target.</li><li>Section counts keep recipe-level errors discoverable.</li></ul><p><strong>Proposed:</strong> the mobile unsaved-changes bottom sheet.</p>'}
function triggerSelector(trigger){if(!trigger)return null;if(trigger.dataset.editIngredient!==undefined)return '[data-edit-ingredient]';if(trigger.dataset.guard!==undefined)return `[data-guard="${trigger.dataset.guard}"]`;return null}function openLayer(layer,trigger){state.layer=layer;state.trigger=triggerSelector(trigger);renderLayer();requestAnimationFrame(()=>layers.querySelector('[data-initial-focus]')?.focus())}function closeLayer(){const selector=state.trigger;state.layer=null;renderLayer();requestAnimationFrame(()=>selector&&app.querySelector(selector)?.focus())}function focusTarget(target){state.openSection=target==='ingredients'?'ingredients':'basics';render();requestAnimationFrame(()=>{const el=target==='ingredients'?app.querySelector('#ingredients'):app.querySelector(`#${target}`);el?.scrollIntoView({block:'start'});el?.focus()})}
function failedSave(){state.showSummary=true;state.openSection='basics';state.layer=null;render();requestAnimationFrame(()=>{const s=app.querySelector('.error-summary');s?.focus();s?.scrollIntoView({block:'start'})});announce(`${issueCount()} issues need attention.`)}function save(){if(issueCount()){failedSave();return}state.navigated='saved';state.layer=null;render();announce('Recipe saved.')}
function syncBasicsHeader(){const toggle=app.querySelector('[data-section="basics"]');if(!toggle)return;const errors=basicIssues().length;toggle.setAttribute('aria-label',`Basics${errors?`, ${errors} ${errors===1?'error':'errors'}`:''}`);const meta=toggle.querySelector('small');if(meta)meta.textContent=`${errors?`${errors} ${errors===1?'error':'errors'} · `:''}7 fields`}
function syncSummary(){const scroll=app.querySelector('.editor-scroll'),existing=scroll?.querySelector('.error-summary'),markup=summary();if(!scroll)return;if(!markup){existing?.remove();return}const template=document.createElement('template');template.innerHTML=markup;const next=template.content.firstElementChild;if(existing)existing.replaceWith(next);else scroll.prepend(next)}
function updateInput(input,preserveFocus=true){const name=input.name;state.fields[name]=input.value;const invalid=fieldInvalid(name),wrapper=input.parentElement,errorId=`error-${name}`;if(invalid)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');if(invalid)input.setAttribute('aria-describedby',errorId);else input.removeAttribute('aria-describedby');const existing=wrapper.querySelector('.field-error');if(invalid&&!existing)wrapper.insertAdjacentHTML('beforeend',`<p class="field-error" id="${errorId}"><span aria-hidden="true">!</span>${basicsCopy[name]}</p>`);if(!invalid&&existing)existing.remove();syncBasicsHeader();syncSummary();if(preserveFocus&&document.activeElement!==input)input.focus({preventScroll:true})}
app.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.section!==undefined){state.openSection=state.openSection===b.dataset.section?'':b.dataset.section;render();return}if(b.dataset.focus!==undefined){e.preventDefault();focusTarget(b.dataset.focus);return}if(b.dataset.editIngredient!==undefined){state.ingredientErrors=false;state.ingredientTouched={};openLayer('ingredient',b);return}if(b.dataset.guard!==undefined){openLayer('guard',b);return}if(b.dataset.save!==undefined){save();return}if(b.dataset.menu!==undefined){state.menu=!state.menu;render();return}if(b.dataset.aux!==undefined){state.menu=false;render();app.querySelector('.auxiliary-message').textContent=`${b.dataset.aux} opens without leaving Edit.`;return}if(b.dataset.removeExcess!==undefined){state.overCapacity=false;render();return}});
app.addEventListener('input',e=>{if(e.target.name&&['title','author','time','servings'].includes(e.target.name))updateInput(e.target)});app.addEventListener('blur',e=>{if(e.target.name==='title'){state.touched.title=true;updateInput(e.target,false)}},true);
function syncIngredientField(input){const name=input.name;state.fields[name]=input.value;const invalid=ingredientInvalid(name),errorId=`${name}-error`,copy=name==='ingredient'?'Enter an ingredient name.':'Enter a quantity using numbers, fractions, or a range.';if(invalid)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');if(invalid)input.setAttribute('aria-describedby',errorId);else input.removeAttribute('aria-describedby');const existing=input.parentElement.querySelector(`#${errorId}`);if(invalid&&!existing)input.insertAdjacentHTML('afterend',`<p class="field-error" id="${errorId}"><span aria-hidden="true">!</span>${copy}</p>`);if(!invalid&&existing)existing.remove()}
layers.addEventListener('input',e=>{if(e.target.name==='ingredient'||e.target.name==='quantity')syncIngredientField(e.target)});layers.addEventListener('blur',e=>{if(e.target.name==='quantity'){state.ingredientTouched.quantity=true;syncIngredientField(e.target)}},true);layers.addEventListener('click',e=>{const b=e.target.closest('button,[data-dismiss]');if(!b)return;if(b.dataset.done!==undefined){state.ingredientErrors=true;renderLayer();requestAnimationFrame(()=>layers.querySelector(ingredientInvalid('ingredient')?'#ingredient':'#quantity')?.focus());return}if(b.dataset.guardSave!==undefined){save();return}if(b.dataset.discard!==undefined){state.layer=null;state.navigated='discarded';render();return}if(b.hasAttribute('data-dismiss'))closeLayer()});
let swipe;layers.addEventListener('pointerdown',e=>{if(e.target.closest('[data-swipe]'))swipe=e.clientY});layers.addEventListener('pointerup',e=>{if(swipe===undefined)return;const d=e.clientY-swipe;swipe=undefined;if(d>=96)closeLayer()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.layer){e.preventDefault();closeLayer();return}if(e.key==='Tab'&&state.layer){const controls=[...layers.querySelectorAll('[role="dialog"] button,[role="dialog"] input')].filter(x=>!x.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});history.replaceState({editBase:true},'',location.href);history.pushState({editGuard:true},'',location.href);window.addEventListener('popstate',()=>{if(!state.layer&&!state.navigated){openLayer('guard',app.querySelector('[data-guard="back"]'));history.pushState({editGuard:true},'',location.href)}});toolbar.addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(!b)return;state.scenario=b.dataset.scenario;state.openSection=b.dataset.scenario==='ingredients'?'ingredients':'basics';state.showSummary=true;state.layer=null;state.menu=false;state.navigated='';state.overCapacity=true;state.ingredientErrors=false;state.ingredientTouched={};state.touched={title:true};Object.assign(state.fields,{title:'',author:'Marta Cooks has a name that is intentionally much too long for this demonstration',time:'4x',servings:'two',ingredient:'',quantity:'two cans'});document.querySelectorAll('[data-scenario]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();if(state.scenario==='guard')requestAnimationFrame(()=>openLayer('guard',app.querySelector('[data-guard="back"]')))});window.mobileEditValidationPrototype={getState:()=>JSON.parse(JSON.stringify(state)),whole,quantity,partialQuantity};render();
